using System.Linq;

namespace Samples;

public static class Demo
{
    public static Dictionary<string, int> CountWords_v2(string text)
    {
        var counts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        var cleaned = new string(text.Select(ch => char.IsLetterOrDigit(ch) ? ch : ' ').ToArray());
        foreach (var word in cleaned.Split(' ', StringSplitOptions.RemoveEmptyEntries))
        {
            counts.TryGetValue(word, out var current);
            counts[word] = current + 1;
        }
        return counts;
    }

    public static void Main()
    {
        const string text = "alpha alpha code review alpha alpha";
        var top = CountWords_v2(text)
            .OrderByDescending(pair => pair.Value)
            .ThenBy(pair => pair.Key)
            .Take(2);

        foreach (var pair in top)
        {
            Console.WriteLine(pair.Key + ":" + pair.Value);
        }
    }
}

