// generic-max | select-maximum / generic-constraint | negative / p4
// Compact variant.

using System;
using System.Collections.Generic;
using System.Linq;

namespace Samples;

public static class Demo
{
    public static T Max_v2<T>(IReadOnlyList<T> values) where T : IComparable<T>
    {
        if (values.Count == 0) throw new ArgumentException("empty list");
        var best = values[0];
        for (var i = 1; i < values.Count; i++)
        {
            if (values[i].CompareTo(best) > 0) best = values[i];
        }
        return best;
    }

    public static void Main()
    {
        Console.WriteLine("int=" + Max_v2(new[] { -21, -8, 0, 21, 6 }));
        Console.WriteLine("str=" + Max_v2(new[] { "delta", "code", "review" }));
        Console.WriteLine("double=" + Max_v2(new[] { -21.5, -8.25 }));
        Console.WriteLine("count=" + new[] { 1, 2, 3 }.Count());
    }
}

